/**
 * The logos of the apps Pim brings, by app id, as `data:` URLs so no page
 * loads them from the services. Marks from Simple Icons (CC0) in each
 * brand's colour, a dark one on a tile of its own so it shows on dark themes
 * too; the rest are the services' own icons, from their sites.
 */

const svg = (body: string, viewBox = "0 0 24 24") =>
	`data:image/svg+xml,${encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="${viewBox}">${body}</svg>`)}`;

/** A 24×24 mark in a colour. */
const mark = (path: string, fill: string) => svg(`<path fill="${fill}" d="${path}"/>`);

/** A 24×24 mark on a rounded tile. */
const onTile = (path: string, fill: string, tile: string) =>
	svg(`<rect width="24" height="24" rx="5.5" fill="${tile}"/><path transform="translate(4.5 4.5) scale(.625)" fill="${fill}" d="${path}"/>`);

